// Scene "main": graph of "guard" (object 40)
class FlowGraphScript_0_40 : public Script {
 public:
  void update(ScriptContext& ctx) override {
    if (ctx.scene != 0) return;
    if (ctx.sceneGeneration != generation) {
      // scene was (re)loaded - back to the initial state
      generation = ctx.sceneGeneration;
      frame = 0;
      started = false;
      seen1 = false;
    }
    frame++;
    {
      const bool isSeen = navPlayerSeen(ctx, 40, 30.0F, 100.0F, 1);
      if (isSeen && !seen1) {
      navChase(ctx, 40, 3.5F, 7.0F, 0.0F);
      }
      seen1 = isSeen;
    }
    if (wpnWasKilled(ctx, 40)) {
      navStop(ctx, 40);
    }
  }

 private:
  unsigned int generation = 0;
  int frame = 0;
  bool started = false;
  bool seen1 = false;
};

